function addBits(a, b) {
  var n = a.length, c = 0, s = '', cin = 0;
  for (var i = n - 1; i >= 0; i--) {
    var x = a[i] === '1' ? 1 : 0, y = b[i] === '1' ? 1 : 0;
    if (i === 0) cin = c;
    var sum = x ^ y ^ c;
    c = (x & y) | (c & (x ^ y));
    s = sum + s;
  }
  return { sum: s, carryOut: c, overflow: (cin ^ c) === 1 };
}
